INSERT INTO questions (id, course_id, specialty_id, subspecialty_id, subject_id, difficulty, enunciado, options, correct_option_id, explanation, metadata, fonte, status_validacao) VALUES 
('QRUB-EBS-2026-001', 'medicina', 'medicina-preventiva-social', 'geral', 'legislacao-ebserh', 'Médio', 'A Empresa Brasileira de Serviços Hospitalares (EBSERH) foi criada pela Lei nº 12.550/2011 com o objetivo principal de prestar serviços gratuitos de assistência médico-hospitalar, ambulatorial e de apoio diagnóstico e terapêutico à comunidade. De acordo com o Art. 2º desta lei, em qual âmbito esses serviços devem ser prestados?', '[{"id":"a","text":"Exclusivamente no âmbito de hospitais filantrópicos conveniados."},{"id":"b","text":"Integrados exclusivamente às Secretarias Estaduais de Saúde."},{"id":"c","text":"No âmbito do Sistema Único de Saúde (SUS) e integrados às Instituições Federais de Ensino Superior ou instituições congêneres."},{"id":"d","text":"Em regime de mercado, competindo com operadoras de saúde suplementar."},{"id":"e","text":"Focados apenas em pacientes com planos de saúde cadastrados."}]', 'c', 'Pela Lei nº 12.550/2011, a EBSERH tem o dever de atuar no âmbito do SUS, vinculada ao Ministério da Educação, servindo como campo de prática e ensino para as Instituições Federais de Ensino Superior (IFES).', '{"origem":"EBSERH 2026'', ''concurso'': ''Ebserh/FGV'', ''ano'': 2026"}', 'ia', 'APROVADA'),
('QRUB-EBS-2026-002', 'medicina', 'clinica-medica', 'cardiologia', 'ic', 'Difícil', 'Paciente masculino, 64 anos, com Insuficiência Cardíaca de Fração de Ejeção Reduzida (ICFEr = 32%). Sinais vitais: PA: 112/68 mmHg. FC: 72 bpm. T: 36,4 °C. FR: 18 irpm. Já utiliza Enalapril 10 mg 12/12h, Carvedilol 25 mg 12/12h e Espironolactona 25 mg/dia. Persiste em Classe Funcional III (NYHA). Segundo a Diretriz Brasileira de IC (SBC 2021), qual a conduta para otimização terapêutica conforme o Edital EBSERH/2026?', '[{"id":"a","text":"Substituir o Enalapril por Sacubitril-Valsartana (ARNI) e considerar adição de iSGLT2."},{"id":"b","text":"Aumentar a dose de Espironolactona para 50 mg/dia."},{"id":"c","text":"Puncionar e drenar edema de membros inferiores."},{"id":"d","text":"Adicionar Nifedipino após o Enalapril."},{"id":"e","text":"Suspender o Carvedilol para melhorar a perfusão periférica."}]', 'a', 'A conduta ''quadrúpla'' clássica (IECA/BRA ou ARNI + Beta-bloq + AM + iSGLT2) é a recomendação atual Nível I A para ICFEr sintomático.', '{"origem":"EBSERH 2026","perfil":"Especialista"}', 'ia', 'APROVADA') 
